using Microsoft.Data.Sqlite;

namespace DeckTester;

// Editorial content is supplied by its author, never generated by a UI template.
public sealed record AiNoteRecord(string Id,string Scope,string Subject,string Title,string Body,
    string Author,string Model,DateTimeOffset WrittenAt,string Evidence,string? Context=null,
    string? RunId=null,string? ExactModelId=null);

public sealed class AiNoteStore
{
    private readonly string connection;
    public AiNoteStore(AppPaths paths)
    {
        connection=new SqliteConnectionStringBuilder { DataSource=Path.Combine(paths.Data,"simulator.sqlite"),DefaultTimeout=30 }.ToString();
        using var db=Open();using var cmd=db.CreateCommand();
        cmd.CommandText="""
            CREATE TABLE IF NOT EXISTS ai_notes(
                id TEXT PRIMARY KEY,scope TEXT NOT NULL,subject TEXT NOT NULL,
                written_at TEXT NOT NULL,run_id TEXT REFERENCES runs(id) ON DELETE CASCADE,payload TEXT NOT NULL);
            CREATE INDEX IF NOT EXISTS ai_notes_subject ON ai_notes(scope,subject,written_at DESC);
            """;
        cmd.ExecuteNonQuery();
        var configured=Environment.GetEnvironmentVariable("CRUCIBLE_NOTES_FILE");
        var seed=configured??Path.Combine(paths.Assets,"src","DeckTester","notes","editorial.json");
        if(configured is null&&!File.Exists(seed))seed=Path.Combine(AppContext.BaseDirectory,"notes","editorial.json");
        if(configured is not null&&!File.Exists(seed))throw new FileNotFoundException("Configured notes file is missing.",seed);
        if(File.Exists(seed)){
            var notes=Json.Decode<List<AiNoteRecord>>(File.ReadAllText(seed));
            // Validate the whole batch before publishing any of it.
            foreach(var note in notes)Validate(note);
            using var tx=db.BeginTransaction();
            foreach(var note in notes){
                if(!SubjectExists(db,tx,note))continue; // A portable catalog can include lists absent on another installation.
                Append(db,tx,note);
            }
            tx.Commit();
        }
    }
    private SqliteConnection Open(){var db=new SqliteConnection(connection);db.Open();using var cmd=db.CreateCommand();cmd.CommandText="PRAGMA foreign_keys=ON";cmd.ExecuteNonQuery();return db;}
    public List<AiNoteRecord> Read(string scope,string subject)
    {
        using var db=Open();using var cmd=db.CreateCommand();
        cmd.CommandText="SELECT payload FROM ai_notes WHERE scope=$scope AND subject=$subject ORDER BY written_at DESC,id DESC";
        cmd.Parameters.AddWithValue("$scope",scope);cmd.Parameters.AddWithValue("$subject",subject);
        using var reader=cmd.ExecuteReader();var notes=new List<AiNoteRecord>();
        while(reader.Read())notes.Add(Json.Decode<AiNoteRecord>(reader.GetString(0)));
        return notes;
    }
    public void Append(AiNoteRecord note)
    {
        Validate(note);
        using var db=Open();using var tx=db.BeginTransaction();
        if(!SubjectExists(db,tx,note))throw new ArgumentException("The note's deck or session does not exist.");
        Append(db,tx,note);tx.Commit();
    }
    private static bool SubjectExists(SqliteConnection db,SqliteTransaction tx,AiNoteRecord note)
    {
        using var cmd=db.CreateCommand();cmd.Transaction=tx;
        cmd.CommandText="SELECT ( $scope!='deck' OR EXISTS(SELECT 1 FROM decks WHERE id=$subject)) AND ($run IS NULL OR EXISTS(SELECT 1 FROM runs WHERE id=$run))";
        cmd.Parameters.AddWithValue("$scope",note.Scope);cmd.Parameters.AddWithValue("$subject",note.Subject);cmd.Parameters.AddWithValue("$run",(object?)note.RunId??DBNull.Value);
        return Convert.ToBoolean(cmd.ExecuteScalar());
    }
    private static void Append(SqliteConnection db,SqliteTransaction tx,AiNoteRecord note)
    {
        using var cmd=db.CreateCommand();cmd.Transaction=tx;
        cmd.CommandText="SELECT payload FROM ai_notes WHERE id=$id";cmd.Parameters.AddWithValue("$id",note.Id);
        if(cmd.ExecuteScalar() is string existing){
            if(Json.Decode<AiNoteRecord>(existing)!=note)throw new InvalidOperationException("AI notes are immutable. Publish a new note ID to revise commentary.");
            return;
        }
        cmd.CommandText="INSERT INTO ai_notes(id,scope,subject,written_at,run_id,payload) VALUES($id,$scope,$subject,$time,$run,$payload)";
        cmd.Parameters.AddWithValue("$scope",note.Scope);cmd.Parameters.AddWithValue("$subject",note.Subject);
        cmd.Parameters.AddWithValue("$time",note.WrittenAt.ToUniversalTime().ToString("O"));cmd.Parameters.AddWithValue("$run",(object?)note.RunId??DBNull.Value);
        cmd.Parameters.AddWithValue("$payload",Json.Encode(note));cmd.ExecuteNonQuery();
    }
    private static void Validate(AiNoteRecord note)
    {
        if(note.Scope is not ("page" or "deck" or "pilot" or "chart" or "run"))throw new ArgumentException("Unknown AI note scope.");
        foreach(var (value,limit) in new[]{(note.Id,128),(note.Subject,256),(note.Title,160),(note.Body,12000),(note.Author,120),(note.Model,120),(note.Evidence,4000)})
            if(string.IsNullOrWhiteSpace(value)||value.Length>limit)throw new ArgumentException("AI note content, evidence, and author signature are required within the documented limits.");
        if(note.WrittenAt==default||note.WrittenAt>DateTimeOffset.UtcNow.AddMinutes(5))throw new ArgumentException("Provide the actual authoring time.");
        if(note.Context?.Length>512||note.ExactModelId?.Length>160)throw new ArgumentException("AI note provenance is too long.");
        if(note.Scope=="run"&&note.Subject!=note.RunId)throw new ArgumentException("A run note must reference its exact session.");
    }
}
